// This file is written by hand, not generated by sqlc. sqlc cannot batch a
// :one query, so these methods run the generated private network deployment
// lookups for many keys at once. They reuse the generated SQL and must bind
// arguments in the order of the generated single-key methods.

package db

import (
	"context"
	"slices"
	"strconv"
	"strings"
)

const privateNetworkLookupChunkSize = 100

// FindPrivateNetworkPreviewDeploymentIds runs
// [Queries.FindPrivateNetworkPreviewDeploymentId] for every key and returns
// the found IDs in key order, empty where a key matches no deployment.
func (q *Queries) FindPrivateNetworkPreviewDeploymentIds(ctx context.Context, keys []FindPrivateNetworkPreviewDeploymentIdParams) ([]string, error) {
	return findDeploymentIDs(ctx, q.db, findPrivateNetworkPreviewDeploymentId, keys, func(arg FindPrivateNetworkPreviewDeploymentIdParams) []any {
		return []any{arg.AppID, arg.GitBranch, arg.ForkKey, arg.WorkspaceID, arg.ProjectID}
	})
}

// FindPrivateNetworkEnvironmentDeploymentIds runs
// [Queries.FindPrivateNetworkEnvironmentDeploymentId] for every key and
// returns the found IDs in key order, empty where a key matches no deployment.
func (q *Queries) FindPrivateNetworkEnvironmentDeploymentIds(ctx context.Context, keys []FindPrivateNetworkEnvironmentDeploymentIdParams) ([]string, error) {
	return findDeploymentIDs(ctx, q.db, findPrivateNetworkEnvironmentDeploymentId, keys, func(arg FindPrivateNetworkEnvironmentDeploymentIdParams) []any {
		return []any{arg.AppID, arg.EnvironmentID, arg.WorkspaceID, arg.ProjectID}
	})
}

func findDeploymentIDs[K any](ctx context.Context, db DBTX, query string, keys []K, args func(K) []any) ([]string, error) {
	ids := make([]string, len(keys))
	slot := 0
	for chunk := range slices.Chunk(keys, privateNetworkLookupChunkSize) {
		var statement strings.Builder
		var params []any
		for i, key := range chunk {
			if i > 0 {
				statement.WriteString(" UNION ALL ")
			}
			statement.WriteString("SELECT " + strconv.Itoa(slot) + " AS slot, newest.id FROM (" + query + ") AS newest")
			params = append(params, args(key)...)
			slot++
		}
		if err := scanDeploymentIDs(ctx, db, statement.String(), params, ids); err != nil {
			return nil, err
		}
	}
	return ids, nil
}

func scanDeploymentIDs(ctx context.Context, db DBTX, statement string, params []any, ids []string) error {
	rows, err := db.QueryContext(ctx, statement, params...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var slot int
		var id string
		if err := rows.Scan(&slot, &id); err != nil {
			return err
		}
		ids[slot] = id
	}
	return rows.Err()
}
